import * as GeometryUtils from '../helpers/geometry.helpers';
import type * as Notes from '../types/notes.types';
import { DEFAULT_NOTE_COLOR } from './note-colors.constants';

export const INITIAL_NOTES_STATE: Notes.NotesState = { notes: [] };

/**
 * Pure reducer for the board's notes. It never mutates `state` and keeps the
 * references of untouched notes, so memoised note components skip re-rendering.
 * Ids are generated by the caller: a reducer that called `crypto.randomUUID()`
 * would not be pure, and StrictMode's double invocation would expose it.
 *
 * @param state - The current notes
 * @param action - What happened
 * @returns The next notes state
 */
export const notesReducer = (
  state: Notes.NotesState,
  action: Notes.NotesAction
): Notes.NotesState => {
  switch (action.type) {
    case 'createNote':
      return {
        ...state,
        notes: [
          ...state.notes,
          { id: action.id, ...action.rect, color: DEFAULT_NOTE_COLOR, text: '' },
        ],
      };
    case 'moveNote':
      return updateNoteRect(state, action.id, (note) => ({
        ...note,
        x: action.position.x,
        y: action.position.y,
      }));
    case 'resizeNote':
      return updateNoteRect(state, action.id, (note) => ({
        ...note,
        width: action.size.width,
        height: action.size.height,
      }));
    case 'deleteNote':
      return deleteNote(state, action.id);
    case 'setNoteColor': {
      const note = state.notes.find((candidate) => candidate.id === action.id);
      // Same color: `state` itself, so a click on the current swatch renders nothing.
      if (!note || note.color === action.color) return state;
      const nextNote = { ...note, color: action.color };
      return {
        ...state,
        notes: state.notes.map((candidate) => (candidate === note ? nextNote : candidate)),
      };
    }
    case 'setNoteText': {
      const note = state.notes.find((candidate) => candidate.id === action.id);
      if (!note || note.text === action.text) return state;
      const nextNote = { ...note, text: action.text };
      return {
        ...state,
        notes: state.notes.map((candidate) => (candidate === note ? nextNote : candidate)),
      };
    }
  }
};

/** Removes one note. An unknown id returns `state` itself, so nothing re-renders. */
const deleteNote = (state: Notes.NotesState, id: string): Notes.NotesState => {
  const notes = state.notes.filter((note) => note.id !== id);
  if (notes.length === state.notes.length) return state;
  return { ...state, notes };
};

/**
 * Replaces one note's rect. An unknown id or an unchanged rect returns `state`
 * itself, so a drag that ends where it started re-renders nothing.
 */
const updateNoteRect = (
  state: Notes.NotesState,
  id: string,
  getNextNote: (note: Notes.Note) => Notes.Note
): Notes.NotesState => {
  const note = state.notes.find((candidate) => candidate.id === id);
  if (!note) return state;
  const nextNote = getNextNote(note);
  if (GeometryUtils.isSameRect(note, nextNote)) return state;
  return {
    ...state,
    notes: state.notes.map((candidate) => (candidate === note ? nextNote : candidate)),
  };
};
